644	#[derive(Debug)]
645	pub(crate) enum ResolutionError {
646	    /// The symbol is imported, but the import came after the current location.
647	    ImportAfterUsage,
648	    /// The symbol is imported, but in an incompatible context (e.g., in typing-only context, while
649	    /// we're in a runtime context).
650	    IncompatibleContext,
651	    /// The symbol can't be imported, because another symbol is bound to the same name.
