658	    fn fmt(&self, fmt: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
659	        match self {
660	            ResolutionError::ImportAfterUsage => {
661	                fmt.write_str("Unable to use existing symbol due to late binding")
662	            }
663	            ResolutionError::IncompatibleContext => {
664	                fmt.write_str("Unable to use existing symbol due to incompatible context")
665	            }
666	            ResolutionError::ConflictingName(binding) => std::write!(
